public Mono<UserDto> fetchUserWithFallback(String userId) {
    return webClient.get()
        .uri("/users/{id}", userId)
        .retrieve()
        .bodyToMono(UserDto.class)
        .timeout(Duration.ofMillis(800))
        .onErrorResume(TimeoutException.class, ex -> cacheService.getUser(userId))
        .onErrorMap(WebClientResponseException.NotFound.class, ex -> new UserNotFoundException("User not found: " + userId))
        .retryWhen(Retry.backoff(3, Duration.ofMillis(100))
            .filter(throwable -> throwable instanceof IOException));
}
